+// CDCL v2 domain model: solver-owned boolean search state.
+// CDCL = Conflict-Driven Clause Learning; BCP = Boolean Constraint Propagation.
+// https://github.com/tiansivive/z-yap/blob/main/zettels/cdcl-t-solver.md
+
+import * as Core from "./core";
+
+export type Variable = number;
+export type Literal = number;
+
+export type Assignment = "true" | "false" | "unassigned";
+
+export type Clause = {
+	readonly id: number;
+	readonly literals: readonly Literal[];
+	readonly origin: string;
+};
+
+export type Conflict = {
+	readonly clause: Clause;
+};
+
+export type TrailReason = Clause | "decision";
+
+export type TrailEntry = {
+	readonly literal: Literal;
+	readonly level: number;
+	readonly reason: TrailReason;
+};
+
+export type ClauseDb = {
+	readonly base: readonly Clause[];
+	readonly learned: readonly Clause[];
+	readonly lemmas: readonly Clause[];
+};
+
+export type State = {
+	readonly trail: readonly TrailEntry[];
+	readonly assignments: ReadonlyMap<Variable, Assignment>;
+	readonly level: number;
+	readonly clauses: ClauseDb;
+	readonly nextClauseId: number;
+};
+
+export type Result =
+	| { readonly tag: "sat"; readonly assignments: ReadonlyMap<Variable, Assignment> }
+	| { readonly tag: "unsat"; readonly core: readonly Clause[] }
+	| { readonly tag: "unknown"; readonly reason: string };
+
+export const Literal = {
+	variable: (lit: Literal): Variable => Math.abs(lit),
+	polarity: (lit: Literal): boolean => lit > 0,
+	negate: (lit: Literal): Literal => -lit,
+};
+
+export const Clauses = {
+	empty: { base: [], learned: [], lemmas: [] } satisfies ClauseDb,
+
+	all: (db: ClauseDb): readonly Clause[] => [...db.base, ...db.learned, ...db.lemmas],
+
+	add: (kind: ClauseKind, clause: Clause) =>
+		Core.State.modify(s => ({
+			...s,
+			cdcl: { ...s.cdcl, clauses: Clauses.insert(s.cdcl.clauses, kind, clause) },
+		})),
+
+	insert: (db: ClauseDb, kind: ClauseKind, clause: Clause): ClauseDb => ({
+		...db,
+		[kind]: [...db[kind], clause],
+	}),
+
+	next: function* (): Core.G<number> {
+		const s = yield* Core.State.get();
+		const id = s.cdcl.nextClauseId;
+		yield* Core.State.modify(st => ({ ...st, cdcl: { ...st.cdcl, nextClauseId: id + 1 } }));
+		return id;
+	},
+};
+
+export type ClauseKind = keyof ClauseDb;
+
+export const Search = {
+	initial: {
+		trail: [],
+		assignments: new Map(),
+		level: 0,
+		clauses: Clauses.empty,
+		nextClauseId: 0,
+	} satisfies State,
+
+	replace: (cdcl: State) => Core.State.modify(s => ({ ...s, cdcl })),
+
+	enter: Core.State.modify(s => ({ ...s, cdcl: { ...s.cdcl, level: s.cdcl.level + 1 } })),
+
+	jump: (level: number) => Core.State.modify(s => ({ ...s, cdcl: backjump(s.cdcl, level) })),
+};
+
+export const Trail = {
+	assign: (literal: Literal, reason: TrailReason) =>
+		Core.State.modify(s => ({
+			...s,
+			cdcl: assign(s.cdcl, literal, reason),
+		})),
+
+	clear: Core.State.modify(s => ({
+		...s,
+		cdcl: { ...s.cdcl, trail: [], assignments: reset(s.cdcl.assignments), level: 0 },
+	})),
+};
+
+const assign = (state: State, literal: Literal, reason: TrailReason): State => ({
+	...state,
+	trail: [...state.trail, { literal, level: state.level, reason }],
+	assignments: new Map([...state.assignments, [Literal.variable(literal), Literal.polarity(literal) ? "true" : "false"]]),
+});
+
+const backjump = (state: State, level: number): State => {
+	const trail = state.trail.filter(entry => entry.level <= level);
+	const assigned = trail.reduce<ReadonlyMap<Variable, Assignment>>(
+		(acc, entry) => new Map([...acc, [Literal.variable(entry.literal), Literal.polarity(entry.literal) ? "true" : "false"]]),
+		new Map(),
+	);
+
+	return {
+		...state,
+		trail,
+		assignments: new Map([...state.assignments.keys()].map(v => [v, assigned.get(v) ?? "unassigned"])),
+		level,
+	};
+};
+
+const reset = (assignments: ReadonlyMap<Variable, Assignment>): ReadonlyMap<Variable, Assignment> =>
+	new Map([...assignments.keys()].map(v => [v, "unassigned" as const]));
*** End Patch

