+// EUF v2 domain model: hash-consed terms and congruence-closure state.
+// EUF = Equality with Uninterpreted Functions; enodes are arena terms.
+// https://github.com/tiansivive/z-yap/blob/main/zettels/euf-theory.md
+
+import { match, P } from "ts-pattern";
+import type { IVL } from "../ivl/types";
+import type { Literal } from "./cdcl";
+
+export type EnodeId = number;
+
+export type Enode = {
+	readonly id: EnodeId;
+	readonly head: string;
+	readonly args: readonly EnodeId[];
+	readonly sort: IVL.Sort;
+};
+
+export type ArenaState = {
+	readonly nodes: ReadonlyMap<EnodeId, Enode>;
+	readonly hashIndex: ReadonlyMap<string, EnodeId>;
+	readonly nextId: number;
+};
+
+export type UnionFindEntry = {
+	readonly parent: EnodeId;
+	readonly rank: number;
+};
+
+export type Equality = {
+	readonly a: EnodeId;
+	readonly b: EnodeId;
+	readonly positive: boolean;
+};
+
+export type MergeReason = {
+	readonly a: EnodeId;
+	readonly b: EnodeId;
+	readonly reason: Literal;
+};
+
+export type Propagation = {
+	readonly literals: readonly Literal[];
+	readonly justification: readonly Literal[];
+};
+
+export type Snapshot = {
+	readonly uf: ReadonlyMap<EnodeId, UnionFindEntry>;
+	readonly mergeLog: readonly MergeReason[];
+};
+
+export type CCState = {
+	readonly uf: ReadonlyMap<EnodeId, UnionFindEntry>;
+	readonly parents: ReadonlyMap<EnodeId, ReadonlySet<EnodeId>>;
+	readonly mergeLog: readonly MergeReason[];
+	readonly literalMap: ReadonlyMap<Literal, Equality>;
+	readonly pending: readonly Propagation[];
+	readonly stack: readonly Snapshot[];
+};
+
+export namespace Arena {
+	export const empty: ArenaState = {
+		nodes: new Map(),
+		hashIndex: new Map(),
+		nextId: 0,
+	};
+
+	export const intern = (state: ArenaState, head: string, args: readonly EnodeId[], sort: IVL.Sort): Interned =>
+		match(state.hashIndex.get(key(head, args)))
+			.with(P.number, id => ({ id, state }))
+			.with(undefined, () => {
+				const id = state.nextId;
+				const node: Enode = { id, head, args, sort };
+				return {
+					id,
+					state: {
+						nodes: new Map([...state.nodes, [id, node]]),
+						hashIndex: new Map([...state.hashIndex, [key(head, args), id]]),
+						nextId: id + 1,
+					},
+				};
+			})
+			.exhaustive();
+
+	export const lookup = (state: ArenaState, id: EnodeId): Enode | undefined => state.nodes.get(id);
+
+	export const find = (state: ArenaState, head: string, args: readonly EnodeId[]): EnodeId | undefined => state.hashIndex.get(key(head, args));
+}
+
+export type Interned = {
+	readonly id: EnodeId;
+	readonly state: ArenaState;
+};
+
+export namespace CC {
+	export const empty: CCState = {
+		uf: new Map(),
+		parents: new Map(),
+		mergeLog: [],
+		literalMap: new Map(),
+		pending: [],
+		stack: [],
+	};
+
+	export const init = (arena: ArenaState): CCState => ({
+		...empty,
+		uf: new Map([...arena.nodes.keys()].map(id => [id, { parent: id, rank: 0 }])),
+		parents: parents(arena),
+	});
+
+	export const register = (state: CCState, literal: Literal, equality: Equality): CCState => ({
+		...state,
+		literalMap: new Map([...state.literalMap, [literal, equality]]),
+	});
+
+	export const push = (state: CCState): CCState => ({
+		...state,
+		stack: [...state.stack, { uf: new Map(state.uf), mergeLog: state.mergeLog }],
+	});
+
+	export const pop = (state: CCState): CCState =>
+		match(state.stack[state.stack.length - 1])
+			.with(undefined, () => state)
+			.otherwise(snapshot => ({
+				...state,
+				uf: snapshot.uf,
+				mergeLog: snapshot.mergeLog,
+				stack: state.stack.slice(0, -1),
+			}));
+}
+
+const parents = (arena: ArenaState): ReadonlyMap<EnodeId, ReadonlySet<EnodeId>> => {
+	const empty = new Map([...arena.nodes.keys()].map(id => [id, new Set<EnodeId>()] as const));
+	return [...arena.nodes.values()].reduce(
+		(acc, node) =>
+			node.args.reduce<ReadonlyMap<EnodeId, ReadonlySet<EnodeId>>>(
+				(inner, arg) => new Map([...inner, [arg, new Set([...(inner.get(arg) ?? new Set()), node.id])]]),
+				acc,
+			),
+		empty,
+	);
+};
+
+const key = (head: string, args: readonly EnodeId[]): string =>
+	match(args)
+		.with([], () => head)
+		.otherwise(values => `${head}(${values.join(",")})`);
*** End Patch

