+// Quantifier v2 domain model: instantiation state for E-matching and bounded MBQI.
+// MBQI = Model-Based Quantifier Instantiation.
+// https://github.com/tiansivive/z-yap/blob/main/zettels/quantifier-engine.md
+
+import type { IVL } from "../ivl/types";
+import type { Clause } from "./cdcl";
+import * as Core from "./core";
+
+export type Trigger = {
+	readonly terms: readonly IVL.Term[];
+};
+
+export type Info = {
+	readonly binders: readonly IVL.Binder[];
+	readonly body: IVL.Formula;
+	readonly triggers: readonly Trigger[];
+	readonly origin?: string;
+};
+
+export type Lemma = {
+	readonly clause: Clause;
+	readonly origin: string;
+	readonly generation: number;
+};
+
+export type Substitution = ReadonlyMap<string, IVL.Term>;
+
+export type Instantiation = {
+	readonly substitution: ReadonlyMap<string, string>;
+	readonly simplified: "true" | "false" | "formula";
+};
+
+export type Phase = {
+	readonly round: number;
+	readonly pending: readonly Lemma[];
+};
+
+export type State = {
+	readonly quantifiers: readonly Info[];
+	readonly generation: number;
+	readonly instantiated: ReadonlySet<string>;
+	readonly phase: Phase;
+};
+
+export const State = {
+	empty: {
+		quantifiers: [],
+		generation: 0,
+		instantiated: new Set(),
+		phase: { round: 0, pending: [] },
+	} satisfies State,
+
+	from: (quantifiers: readonly Info[]): State => ({
+		...State.empty,
+		quantifiers,
+	}),
+};
+
+export const Generation = {
+	advance: Core.State.modify(s => ({
+		...s,
+		quantifiers: {
+			...s.quantifiers,
+			generation: s.quantifiers.generation + 1,
+			phase: { ...s.quantifiers.phase, round: s.quantifiers.phase.round + 1 },
+		},
+	})),
+};
