+	match(current)
+		.with({ tag: "True" }, () => Build.andWithOrigin([next], origin))
+		.with({ tag: "And" }, ({ values }) => Build.andWithOrigin([...values, next], origin))
+		.otherwise(f => Build.andWithOrigin([f, next], origin));
