+namespace Tseitin {
+	type State = Enc.State & {
+		readonly nextClauseId: number;
+	};
+
+	type Result = {
+		readonly literal: CDCL.Literal;
+		readonly state: State;
+	};
+
+	const initial: State = {
+		clauses: [],
