+// Boolean Constraint Propagation for v2 CDCL using the v1 scan-based clause classifier.
+// BCP = Boolean Constraint Propagation; watched literals remain deferred by plan.
+// https://github.com/tiansivive/z-yap/blob/main/zettels/cdcl-t-solver.md
+
+import { match, P } from "ts-pattern";
+import * as Trace from "../trace";
+import { Clause, type Assignment, type Literal, Literal as Lit, type State, Trail } from "./model";
+
+export type Result = { readonly tag: "ok"; readonly state: State } | { readonly tag: "conflict"; readonly clause: Clause.T };
+
+type Unit =
+	| { readonly tag: "none" }
+	| { readonly tag: "conflict"; readonly clause: Clause.T }
+	| { readonly tag: "unit"; readonly literal: Literal; readonly reason: Clause.T };
+
+export const propagate = function* (state: State): Trace.Core.G<Result> {
+	const unit = classify(state);
+	return yield* match(unit)
+		.with({ tag: "none" }, () => Trace.Core.lift<Result>({ tag: "ok", state }))
+		.with({ tag: "conflict" }, ({ clause }) => Trace.Core.lift<Result>({ tag: "conflict", clause }))
+		.with({ tag: "unit" }, function* ({ literal, reason }): Trace.Core.G<Result> {
+			yield* Trace.Trace.emit({ tag: "propagate", literal, reason });
+			return yield* propagate(State.assign(state, literal, Trail.Reason.clause(reason)));
+		})
+		.exhaustive();
+};
+
+const classify = (state: State): Unit =>
+	Clause.all(state.clauses)
+		.map(clause => classifyClause(state.assignments, clause))
+		.find((unit): unit is Exclude<Unit, { readonly tag: "none" }> => unit.tag !== "none") ?? { tag: "none" };
+
+const classifyClause = (assignments: ReadonlyMap<Lit.Variable, Assignment>, clause: Clause.T): Unit =>
+	match(satisfied(assignments, clause))
+		.with(true, () => ({ tag: "none" }) satisfies Unit)
+		.with(false, () =>
+			match(clause.literals.filter(lit => assignment(assignments, lit) === "unassigned"))
+				.with([], () => ({ tag: "conflict", clause }) satisfies Unit)
+				.with([P.select()], literal => ({ tag: "unit", literal, reason: clause }) satisfies Unit)
+				.otherwise(() => ({ tag: "none" }) satisfies Unit),
+		)
+		.exhaustive();
+
+const assignment = (assignments: ReadonlyMap<Lit.Variable, Assignment>, lit: Literal): Assignment => assignments.get(Lit.variable(lit)) ?? "unassigned";
+
+const satisfied = (assignments: ReadonlyMap<Lit.Variable, Assignment>, clause: Clause.T): boolean => clause.literals.some(lit => literal(assignments, lit));
+
+const literal = (assignments: ReadonlyMap<Lit.Variable, Assignment>, lit: Literal): boolean =>
+	(Lit.polarity(lit) && assignment(assignments, lit) === "true") || (!Lit.polarity(lit) && assignment(assignments, lit) === "false");
