+import type { Lemma } from "../engine";
+import type { Info } from "../triggers";
+import * as Candidates from "./candidates";
+import type { Candidate, Simplification } from "./grounding";
+import * as Grounding from "./grounding";
+import * as Universe from "./universe";
+
+export const round = (quantifiers: readonly Info[], arena: Arena.State, instantiated: ReadonlySet<string>, generation: number, next: Next, encode: Encode): Result => {
+	const universe = Universe.from(arena, quantifiers);
+	return quantifiers.reduce<Accumulator>(
+		(acc, info) => Candidates.enumerate(info.binders, universe).reduce((subAcc, candidate) => grounded(info, candidate, subAcc, instantiated, generation, next, encode), acc),
+		{ lemmas: [], newKeys: new Set(), instantiations: [] },
+	);
+};
+
+export type Next = () => number;
+
+export type Encode = (formula: IVL.Formula) => readonly Literal[];
+
+export type Result = {
+	readonly lemmas: readonly Lemma[];
+	readonly newKeys: ReadonlySet<string>;
+	readonly instantiations: readonly Instantiation[];
+};
+
+export type Instantiation = {
+	readonly substitution: ReadonlyMap<string, string>;
+	readonly simplification: Simplification;
+};
+
+type Accumulator = Result;
+
+const lemma = (info: Info, generation: number, next: Next, literals: readonly Literal[]): Lemma => ({
+	clause: {
+		id: next(),
+		literals: [...literals],
+		origin: `mbqi:${info.origin ?? "forall"}:gen${generation}`,
+	},
+	origin: info.origin ?? "forall",
+	generation,
+});
+
+const process = (simplification: Simplification, id: string, info: Info, candidate: Candidate, acc: Accumulator, generation: number, next: Next, encode: Encode): Accumulator => {
+	const tracked = {
+		newKeys: new Set([...acc.newKeys, id]),
+		instantiations: [...acc.instantiations, { substitution: Candidates.strings(candidate), simplification }],
+	};
+	return match(simplification)
+		.with({ tag: "tautology" }, () => ({ ...acc, ...tracked }))
+		.with({ tag: "contradiction" }, () => ({ lemmas: [...acc.lemmas, lemma(info, generation, next, [])], ...tracked }))
+		.with({ tag: "residual" }, ({ formula }) =>
+			match(encode(formula))
+				.with([], () => ({ ...acc, ...tracked }))
+				.otherwise(literals => ({ lemmas: [...acc.lemmas, lemma(info, generation, next, literals)], ...tracked })),
+		)
+		.exhaustive();
+};
+
+const grounded = (info: Info, candidate: Candidate, acc: Accumulator, instantiated: ReadonlySet<string>, generation: number, next: Next, encode: Encode): Accumulator => {
+	const id = `mbqi:${info.origin ?? "q"}[${Candidates.key(info.binders, candidate)}]`;
+	return match(instantiated.has(id) || acc.newKeys.has(id))
+		.with(true, () => acc)
+		.with(false, () => process(Grounding.ground(info.body, candidate), id, info, candidate, acc, generation, next, encode))
+		.exhaustive();
